namespace ModernLibs.FileHelpers.Generator.Models;

/// <summary>
/// Equatable pipeline model representing a single annotated record type.
/// Contains ONLY primitives and EquatableArray — no ISymbol, SyntaxNode, or Compilation references.
/// This is a C# record: structural equality is auto-generated by the compiler.
/// </summary>
internal sealed record RecordModel(
    string Namespace,
    string TypeName,
    string TypeKind,
    bool IsReadOnly,
    string RecordKind,
    string Delimiter,
    EquatableArray<FieldModel> Fields,
    string? FixedMode = null,              // null for delimited; "ExactLength"/"AllowMoreChars"/etc for fixed
    int IgnoreFirst = 0,                    // from [IgnoreFirst(N)]
    int IgnoreLast = 0,                     // from [IgnoreLast(N)]
    bool IgnoreEmptyLines = false,          // from [IgnoreEmptyLines]
    char CommentMarker = '\0')              // from [IgnoreCommentedLines(char)]
    ;
